/** Alt+Enter maximizes the active chart of a multi-chart layout, or restores the grid. */
export function isMaximizeChord(event:{key:string;altKey:boolean;ctrlKey:boolean;metaKey:boolean;shiftKey:boolean;repeat?:boolean}):boolean{return event.key==='Enter'&&event.altKey&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey&&!event.repeat;}
/** Tab and Shift+Tab switch the active chart of a multi-chart layout ("Switch between charts").
 * Only from a chart itself: buttons, fields and the grid dividers keep Tab for focus. */
export function isChartCycleKey(event:{key:string;altKey:boolean;ctrlKey:boolean;metaKey:boolean;isComposing?:boolean}):boolean{return event.key==='Tab'&&!event.altKey&&!event.ctrlKey&&!event.metaKey&&!event.isComposing;}
/** True when no control holds focus: the event target is the page body or the document itself. */
export function isBodyFocus(target:Element|null,doc:{body:unknown;documentElement:unknown}):boolean{return!target||target===doc.body||target===doc.documentElement;}
export const CHART_CYCLE_KEEPS_TAB='input,textarea,select,button,a,[contenteditable="true"],[role=menu],[role=dialog],[role=separator],[role=button],[role=tab],[role=slider],[role=radio],[role=listbox]';
/** The chart Tab (or Shift+Tab when `backwards`) makes active, in layout order, wrapping around; null with fewer than two charts. */
export function cycledCellId(cells:readonly {id:string}[],activeId:string,backwards:boolean):string|null{if(cells.length<2)return null;const at=Math.max(0,cells.findIndex(cell=>cell.id===activeId));return cells[(at+(backwards?cells.length-1:1))%cells.length]!.id;}
/** Alt+click on a chart maximizes or restores it ("Toggle maximize chart": Alt+Enter or Alt+click). */
export function isMaximizeClick(event:{button:number;altKey:boolean;ctrlKey:boolean;metaKey:boolean;shiftKey:boolean}):boolean{return event.button===0&&event.altKey&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey;}
